        Colors[21] := '808000'; // Olive      
        Colors[22] := 'DDBB20'; // Golden     
        Colors[23] := 'F0E68C'; // Khaki      

        clBlack    := '202020';

        K  := 0.13;
        s2 := sqrt(2);

        C0 := K * sqrt(2 + s2);
        C1 := K * s2 * sqrt(2 + s2);
        C2 := K * s2 * (s2 - 1 + 2 * sqrt(2 - s2));
        C3 := K * s2 * (1 + sqrt(2 + s2));

        S  := 1.0505;

        D1 := K * (2 * sqrt(2 + s2) - s2) * S;
        D2 := C2 * sqrt((16 * s2 + 23) / 17);
        D3 := s2 * ((C1 + C3) / 2 * (1 - D1 / C2) + D1);

        Rc := K * 0.9;
        R1 := D2 / sqrt(4 * s2 + 7) * (1 + s2);
        R2 := D2 / sqrt(4 * s2 + 7);

        Hx1 := 0;             Hy1 := D1 * s2 - C1 - C3; Hz1 := D1 * s2;
        Hx2 := (C0 + C2) / 2; Hy2 :=-(C0 + C2) / 2;     Hz2 := (C3 + C2) / 2;
        Hx3 := D1;            Hy3 :=-D1;                Hz3 := C3 - (D1 - C0) * s2;
